589	    pub(crate) async fn get_prefix(
590	        &'me self,
591	        prefix: &str,
592	    ) -> Result<impl Iterator<Item = (K, V)>, Box<dyn ChromaError>> {
593	        // Get all block IDs that might contain this prefix
594	        let block_ids = self.root.sparse_index.get_block_ids_range(prefix..=prefix);
595	
596	        if block_ids.is_empty() {
597	            return Ok(Vec::new().into_iter().flatten());
598	        }
599	
600	        // Fetch blocks AND extract prefix data in parallel
601	        let block_futures = block_ids.into_iter().map(|block_id| {
602	            async move {
603	                match self.get_block(block_id, StorageRequestPriority::P0).await {
604	                    Ok(Some(block)) => {
605	                        // Extract prefix data while we're in the async context
606	                        let prefix_data = block.get_prefix::<K, V>(prefix);
607	                        Ok(prefix_data)
608	                    }
609	                    Ok(None) => {
610	                        Err(Box::new(ArrowBlockfileError::BlockNotFound) as Box<dyn ChromaError>)
611	                    }
612	                    Err(e) => Err(Box::new(e) as Box<dyn ChromaError>),
613	                }
614	            }
615	            .instrument(Span::current())
616	        });
617	
618	        let block_iters: Vec<_> = futures::stream::iter(block_futures)
619	            .buffered(self.block_manager.max_concurrent_block_loads())
620	            .try_collect()
621	            .await?;
622	
623	        Ok(block_iters.into_iter().flatten())
624	    }
