626	    // Returns all Arrow records in the specified range.
627	    pub(crate) fn get_range_stream<'prefix, PrefixRange, KeyRange>(
628	        &'me self,
629	        prefix_range: PrefixRange,
630	        key_range: KeyRange,
631	    ) -> impl Stream<Item = Result<(&'me str, K, V), Box<dyn ChromaError>>> + Send + 'me
632	    where
633	        PrefixRange: RangeBounds<&'prefix str> + Clone + Send + 'me,
634	        KeyRange: RangeBounds<K> + Clone + Send + 'me,
635	        K: Sync,
636	        V: Sync,
637	    {
638	        futures::stream::iter(
639	            self.root
640	                .sparse_index
641	                .get_block_ids_range(prefix_range.clone())
642	                .into_iter()
643	                .map(Ok),
644	        )
645	        .try_filter_map(move |block_id| async move {
646	            match self.get_block(block_id, StorageRequestPriority::P0).await {
647	                Ok(Some(block)) => Ok(Some(block)),
648	                Ok(None) => Err(Box::new(ArrowBlockfileError::BlockNotFound)),
649	                Err(e) => Err(Box::new(ArrowBlockfileError::BlockFetchError(e))),
650	            }
651	        })
652	        .map(move |block| match block {
653	            Ok(block) => futures::stream::iter(
654	                block
655	                    .get_range::<K, V, _, _>(prefix_range.clone(), key_range.clone())
656	                    .map(Ok),
657	            )
658	            .boxed(),
659	            Err(e) => futures::stream::once(async { Err(e as Box<dyn ChromaError>) }).boxed(),
660	        })
661	        .flatten()
662	    }
