664	    pub async fn get_range<'prefix, PrefixRange, KeyRange>(
665	        &'me self,
666	        prefix_range: PrefixRange,
667	        key_range: KeyRange,
668	    ) -> Result<impl Iterator<Item = (&'me str, K, V)> + 'me, Box<dyn ChromaError>>
669	    where
670	        PrefixRange: RangeBounds<&'prefix str> + Clone + 'me,
671	        KeyRange: RangeBounds<K> + Clone + 'me,
672	    {
673	        let block_ids = self
674	            .root
675	            .sparse_index
676	            .get_block_ids_range(prefix_range.clone());
677	
678	        let block_futures_is_empty = block_ids.is_empty();
679	        let block_futures = block_ids.into_iter().map(|block_id| {
680	            async move {
681	                match self.get_block(block_id, StorageRequestPriority::P0).await {
682	                    Ok(Some(block)) => Ok(block),
683	                    Ok(None) => {
684	                        Err(Box::new(ArrowBlockfileError::BlockNotFound) as Box<dyn ChromaError>)
685	                    }
686	                    Err(e) => Err(Box::new(e) as Box<dyn ChromaError>),
687	                }
688	            }
689	            .instrument(Span::current())
690	        });
691	
692	        let blocks: Vec<&Block> = if !block_futures_is_empty {
693	            futures::stream::iter(block_futures)
694	                .buffered(self.block_manager.max_concurrent_block_loads())
695	                .try_collect()
696	                .await?
697	        } else {
