/// Default maximum size in bytes for a single posting block. Used when
/// creating blockfile writers for the sparse posting list. A dimension whose
/// serialized entries would exceed this size is split across multiple blocks.
pub const SPARSE_POSTING_BLOCK_SIZE_BYTES: usize = 1 << 16;

#[derive(Debug, Error)]
pub enum MaxScoreError {
    #[error(transparent)]
    Blockfile(#[from] Box<dyn ChromaError>),
    #[error("sparse posting block error: {0}")]
    Block(#[from] SparsePostingBlockError),
}

impl ChromaError for MaxScoreError {
    fn code(&self) -> ErrorCodes {
        match self {
            MaxScoreError::Blockfile(err) => err.code(),
            MaxScoreError::Block(_) => ErrorCodes::Internal,
        }
    }
}

/// Compute the directory blockfile prefix for an encoded dimension key.
fn directory_prefix(encoded_dim: &str) -> String {
    let mut prefix = String::with_capacity(DIRECTORY_PREFIX.len() + encoded_dim.len());
    prefix.push_str(DIRECTORY_PREFIX);
    prefix.push_str(encoded_dim);
    prefix
}

/// Greedily split pre-sorted `(offset, weight)` entries into posting blocks,
/// each of which serializes within `max_bytes`. A single entry that alone
/// exceeds `max_bytes` still occupies its own block. No block ever holds more
/// than [`MAX_BLOCK_ENTRIES`] entries.
fn chunk_into_blocks(
    entries: &[(u32, f32)],
    max_bytes: usize,
) -> Result<Vec<SparsePostingBlock>, SparsePostingBlockError> {
    let mut blocks = Vec::new();
    let n = entries.len();
    let mut start = 0;
    while start < n {
        let mut end = start;
        loop {
            let next = end + 1;
            if next > n || next - start > MAX_BLOCK_ENTRIES {
                break;
            }
            let candidate = SparsePostingBlock::from_sorted_entries(&entries[start..next])?;
            let size = candidate.serialized_size();
            if size <= max_bytes || end == start {
                // Always accept at least one entry, even if it alone is too big.
                end = next;
                if size > max_bytes {
                    break;
                }
            } else {
                break;
            }
        }
        blocks.push(SparsePostingBlock::from_sorted_entries(&entries[start..end])?);
        start = end;
    }
    Ok(blocks)
}

/// Returned by [`MaxScoreWriter::commit`]. Provides access to the posting id
/// and the flush operation.
pub struct MaxScoreFlusher {
    posting_flusher: BlockfileFlusher,
}

impl MaxScoreFlusher {
    pub fn id(&self) -> Uuid {
        self.posting_flusher.id()
    }

    pub async fn flush(self) -> Result<(), MaxScoreError> {
        self.posting_flusher
            .flush::<u32, SparsePostingBlock>()
            .await?;
        Ok(())
    }
}

/// Writes sparse posting lists into a single blockfile.
///
/// Each dimension is stored as one or more [`SparsePostingBlock`] data blocks
/// (prefix = `encode_u32(dim)`, key = block index) plus, when a dimension
/// spans multiple blocks, a per-dimension directory (prefix =
/// `DIRECTORY_PREFIX + encode_u32(dim)`, key = part index).
///
/// The writer buffers all mutations in `delta` until [`commit`](Self::commit).
/// When constructed with an `old_reader`, it merges the existing entries for
/// each touched dimension with the buffered delta; untouched dimensions are
/// carried forward by the underlying forked blockfile writer.
#[derive(Clone)]
pub struct MaxScoreWriter<'me> {
    block_size: usize,
    // dimension_id -> offset -> Some(weight) for upsert, None for delete
    delta: Arc<DashMap<u32, DashMap<u32, Option<f32>>>>,
    posting_writer: BlockfileWriter,
    old_reader: Option<MaxScoreReader<'me>>,
}

impl<'me> MaxScoreWriter<'me> {
    pub fn new(posting_writer: BlockfileWriter, old_reader: Option<MaxScoreReader<'me>>) -> Self {
        Self {
